import {
  post,
  postFile,
} from "@traveloka/soya-components/lib/utils/ServiceUtil";
// import getRulesStructure from './mock/getRulesStructure.json';
// import getVersions from './mock/getVersions.json';
// import loadRuleSet from './mock/loadRuleSet.json';

class CommonRuleService {
  getAccessToken() {
    return localStorage.getItem("access_token");
  }

  loadRuleSet(data) {
    return post(`/api/v2/rules/loadRuleSet`, this.getAccessToken(), data);
    // return new Promise(resolve => {
    //   resolve(loadRuleSet);
    // });
  }

  getAllVersions(data) {
    return post(`/api/v2/rules/getVersions`, this.getAccessToken(), data);
    // return new Promise(resolve => {
    //   resolve(getVersions);
    // });
  }

  saveRuleSet(data) {
    return post(`/api/v2/rules/saveRuleSet`, this.getAccessToken(), data);
  }

  getRulesStructure(data) {
    return post(`/api/v2/rules/getRulesStructure`, this.getAccessToken(), data);
    // return new Promise(resolve => {
    //   resolve(getRulesStructure);
    // });
  }

  importRuleSet(data, file) {
    return postFile(
      `/api/v2/rules/importRuleSet`,
      this.getAccessToken(),
      data,
      { "data.rules": file }
    );
  }

  exportRuleSet(data) {
    return post(`/api/v2/rules/exportRuleSet`, this.getAccessToken(), data);
  }
}

export default CommonRuleService;
